#include "PhysicsWorld.h"
#include <cstdio>
#include <array>
#include <cmath>
#include <stdexcept>
static unsigned checks=0,failures=0;void check(bool v,const char* name){++checks;failures+=!v;std::printf("%s %s\n",v?"PASS":"FAIL",name);}
int main(){PhysicsWorld worlds[2];std::array<BodyHandle,3> bodies[2];JointHandle joint[2];for(unsigned i=0;i<2;++i){auto& w=worlds[i];w.Init();w.CreateStaticBox({-20,-.5,0},{5,.5,5},.6,0);bodies[i][0]=w.CreateDynamicSphere({-20,.3,0},.3,1,.6,0);bodies[i][1]=w.CreateDynamicBox({0,0,0},{.5,.5,.5},2,.5,0);JointSettings settings;settings.bodyA=bodies[i][1];settings.type=JointType::Hinge;settings.spring=true;settings.stiffness=8;settings.damping=1;settings.limits=true;settings.lower=-.8;settings.upper=.8;joint[i]=w.CreateJoint(settings);w.SetAngularVelocity(bodies[i][1],{2,0,0});bodies[i][2]=w.CreateStaticBox({20,0,0},{2,.2,2},.6,0);w.SetMotionType(bodies[i][2],BodyMotionType::Kinematic);w.MoveKinematic(bodies[i][2],{{24,1,0},glm::angleAxis(.4f,glm::vec3(0,1,0))},1);}
 glm::vec3 delta(512,-256,128);auto advance=[&](){for(unsigned i=0;i<2;++i){worlds[i].ApplyForce(bodies[i][0],{0,-9.81,0});worlds[i].Step(1.f/60);}};for(int i=0;i<30;++i)advance();auto& shifted=worlds[1];const auto v=shifted.GetLinearVelocity(bodies[1][0]),angular=shifted.GetAngularVelocity(bodies[1][1]);const bool sleeping=shifted.IsSleeping(bodies[1][0]);auto events=shifted.LastStepTouchEvents();shifted.ShiftOrigin(glm::dvec3(delta));check(shifted.GetLinearVelocity(bodies[1][0])==v&&shifted.GetAngularVelocity(bodies[1][1])==angular,"origin change preserves linear/angular velocity exactly");check(shifted.IsSleeping(bodies[1][0])==sleeping,"origin change does not wake or freeze bodies");check(shifted.LastStepTouchEvents().size()==events.size(),"completed touch publication is retained");bool points=true;for(size_t i=0;i<events.size();++i)points&=glm::length(shifted.LastStepTouchEvents()[i].point+delta-events[i].point)<.0001f;check(points&&!events.empty(),"actual floor contact event points translate with the chart");for(int i=0;i<90;++i)advance();for(unsigned b=0;b<3;++b){check(glm::length(shifted.GetTransform(bodies[1][b]).position+delta-worlds[0].GetTransform(bodies[0][b]).position)<.002f,"warm contact/hinge/moving platform endpoints agree with unshifted control");check(glm::length(shifted.GetLinearVelocity(bodies[1][b])-worlds[0].GetLinearVelocity(bodies[0][b]))<.002f,"continued resolved velocities agree with independent unshifted control");}JointState a,b;worlds[0].GetJoint(joint[0],a);shifted.GetJoint(joint[1],b);check(std::abs(a.coordinate-b.coordinate)<.0001f,"world-anchor hinge continuation preserves actual physical coordinate");auto hit=shifted.Raycast(glm::vec3(-20,2,0)-delta,{0,-1,0},4);check(hit.hit,"translated broadphase retains real ground queries after continued integration");bool invalid=false;try{shifted.ShiftOrigin({NAN,0,0});}catch(const std::exception&){invalid=true;}check(invalid,"nonfinite native origin shifts fail before mutation");std::printf("SUMMARY %u checks %u failures\n",checks,failures);return failures?1:0;}
